'use strict';
const root=document.getElementById('app'),dialog=document.getElementById('dialog'),APP=document.body.dataset.app,BASE=document.body.dataset.base||'',API=document.body.dataset.api;
const S={csrf:'',me:null,schema:null,tenant:'',page:'dashboard',number:1,q:'',status:'',data:null,refs:{},tenants:[],login:null,filters:{}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>new Intl.NumberFormat('ru-RU').format(Number(v)||0), date=v=>v?new Date(String(v).replace(' ','T')+(String(v).includes('T')?'':'Z')).toLocaleString('ru-RU',{timeZone:S.me?.tenant?.settings?.timezone||'Europe/Moscow',dateStyle:'short',timeStyle:'short'}):'—';
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',employees:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0a4 4 0 0 1 8 0',facilities:'M3 21h18 M5 21V7l7-4 7 4v14 M9 9h1 M14 9h1 M9 13h1 M14 13h1 M10 21v-4h4v4',shifts:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',documents:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',contracts:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',attendance:'M12 3v9l6 3 M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0',vacancies:'M4 7h16v14H4z M8 7V3h8v4 M4 12h16 M10 11v3h4v-3',audit:'M8 3h8v4H8z M8 5H5v16h14V5h-3 M8 11h8 M8 15h8',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0a8 8 0 0 1 16 0',arrow:'M5 12h14 M13 6l6 6-6 6',logout:'M9 3H4v18h5 M9 12h12 M16 7l5 5-5 5',menu:'M4 6h16 M4 12h16 M4 18h16',bell:'M18 8a6 6 0 0 0-12 0v6l-2 3h16l-2-3z M10 21h4',check:'M5 12l4 4L19 6',download:'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.documents}"/></svg>`;
const roles={tenant_admin:'Администратор ЧОП',platform_admin:'Оператор платформы',hr:'Кадровик',operations:'Операционный менеджер',object_manager:'Начальник объекта',customer:'Заказчик',guard:'Охранник'};
const statuses={ACTIVE:'Активен',INACTIVE:'Неактивен',ON_LEAVE:'В отпуске',DISMISSED:'Уволен',PENDING_REVIEW:'На проверке',PENDING_SCAN:'В карантине',CLEAN:'Проверен',INFECTED:'Заражён',VALID:'Действителен',EXPIRING:'Истекает',EXPIRED:'Истёк',REJECTED:'Отклонён',DRAFT:'Черновик',PUBLISHED:'Опубликовано',ENDED:'Завершён',DUE:'К исполнению',OVERDUE:'Просрочено',MARKED_SENT:'Отмечено отправленным',CONFIRMED:'Подтверждено',UNFILLED:'Есть свободные места',COMPLETED:'Завершено',CANCELLED:'Отменено',ASSIGNED:'Назначено',DECLINED:'Отклонено',REPLACED:'Заменено',REQUIRES_REVIEW:'Требует решения',MANUAL_OVERRIDE:'Ручное решение',OPEN:'Открыто',IN_PROGRESS:'В работе',RESOLVED:'Решено',MISSED:'Пропущен',CLOSED:'Закрыто',INVITED:'Приглашён',BLOCKED:'Заблокирован',SUSPENDED:'Приостановлен',NEW:'Новое',DONE:'Выполнено'};
function badge(v){const cls=['ACTIVE','VALID','CONFIRMED','COMPLETED','RESOLVED','CLEAN'].includes(v)?'green':['EXPIRED','OVERDUE','REJECTED','INFECTED','DISMISSED','BLOCKED','SUSPENDED'].includes(v)?'red':['UNFILLED','EXPIRING','REQUIRES_REVIEW','PENDING_REVIEW','PENDING_SCAN','DUE'].includes(v)?'amber':'blue';return `<span class="status ${cls}">${esc(statuses[v]||v||'—')}</span>`;}
function can(p){return S.me?.permissions.some(x=>x==='*'||x===p||(x.endsWith('.*')&&p.startsWith(x.slice(0,-1))));}
function toast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6500);}
function url(path,query={}){const params=new URLSearchParams({path:'/v1/'+path,space:APP,...(S.tenant?{tenant:S.tenant}:{}),...query});return API+'?'+params;}
async function api(path,method='GET',data=null,query={},refresh=true){const opts={method,credentials:'same-origin',headers:{}};if(method!=='GET'){opts.headers['X-CSRF-Token']=S.csrf;if(data instanceof FormData)opts.body=data;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data||{});}}const res=await fetch(url(path,query),opts);let json;try{json=await res.json();}catch{throw Error('Сервер вернул некорректный ответ');}if(!res.ok){if(res.status===401&&refresh&&!path.startsWith('auth/')&&path!=='csrf'){try{await api('auth/refresh','POST',{}, {},false);return await api(path,method,data,query,false);}catch{loginView();}}const e=Error(json.message||'Не удалось выполнить действие');e.code=json.code;e.details=json.details;throw e;}return json;}
function showDialog(title,html){dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button aria-label="Закрыть" data-close>×</button></div>${html}`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();}
const apps=[['admin','Администратор'],['client','Заказчик'],['platform','Платформа'],['jobs','Биржа труда']];
function loginView(challenge=null,invite=false){S.login=challenge;const account=APP==='platform'?'platform@choppro.example':APP==='client'?'customer@obereg.example':'admin@obereg.example';const titles={admin:['Вся охрана.<br>В одном пространстве.','Объекты, сотрудники, документы и смены — управляемая работа вашей организации.'],client:['Ваши объекты.<br>Всегда под контролем.','Присутствие на постах, обходы и опубликованные отчёты — в кабинете заказчика.'],platform:['Единая платформа.<br>Пять организаций.','Управление организациями, доступом и состоянием системы.']};const [title,subtitle]=titles[APP]||titles.admin;
root.innerHTML=`<div class="login-layout"><section class="login-story"><div class="brand"><span class="brand-mark">Ч</span>ЧОППРО</div><div><div class="eyebrow">Система управления охраной</div><h1>${title}</h1><p>${subtitle}</p><div class="login-stats"><div><strong>120</strong><span>объектов охраны</span></div><div><strong>1 000</strong><span>сотрудников</span></div><div><strong>10 080</strong><span>смен в графике</span></div></div></div><div class="small muted">Демонстрационное пространство · Этап 2</div></section><section class="login-form-wrap"><div class="login-form"><div class="eyebrow">${esc(apps.find(x=>x[0]===APP)?.[1])}</div><h2>${invite?'Принять приглашение':challenge?'Подтверждение входа':'Добро пожаловать'}</h2><p>${challenge?'Введите код из приложения аутентификации.':invite?'Укажите токен приглашения и новый пароль.':'Войдите, чтобы продолжить работу.'}</p><div id="login-error"></div><form id="login-form">${challenge?`<label>Код подтверждения<input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required placeholder="000000" value="${esc(challenge.demo_code||'')}"></label>${challenge.secret?`<div class="alert">Добавьте ключ в приложение аутентификации: <strong>${esc(challenge.secret)}</strong></div>`:''}${challenge.demo_code?'<div class="alert success">Для тестового аккаунта код уже подставлен. Для рабочих аккаунтов используется приложение аутентификации.</div>':''}`:invite?'<label>Токен приглашения<input name="token" required></label><label>Новый пароль<input name="password" type="password" minlength="10" autocomplete="new-password" required></label>':`<label>Email<input name="email" type="email" autocomplete="username" required value="${account}"></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required value="Demo2026!"></label>`}<button class="btn primary">${challenge?'Подтвердить вход':invite?'Активировать аккаунт':'Войти в систему'} ${icon('arrow')}</button></form>${!challenge&&!invite?`<div class="demo-access"><strong>Доступ к наполненному демо</strong>${esc(account)}<br>Пароль: <b>Demo2026!</b>${APP==='admin'?'<br><button data-account="hr">Кадровик</button> · <button data-account="operations">Операционный менеджер</button> · <button data-account="manager">Начальник объекта</button>':''}<br><button id="invite-link">Принять приглашение</button></div>`:'<button class="link" id="login-back">← Назад ко входу</button>'}<div class="switch-links">${apps.filter(x=>x[0]!==APP).map(([key,label])=>`<a href="${BASE}/demo.php?app=${key}" target="_blank" rel="noopener">${label} ↗</a>`).join('')}</div></div></section></div>`;
root.querySelectorAll('[data-account]').forEach(el=>el.onclick=()=>root.querySelector('[name=email]').value=el.dataset.account+'@obereg.example');root.querySelector('#invite-link')?.addEventListener('click',()=>loginView(null,true));root.querySelector('#login-back')?.addEventListener('click',()=>loginView());
root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(invite){await api('auth/invite','POST',data);toast('Аккаунт активирован');loginView();return;}const out=await api(challenge?'auth/mfa/verify':'auth/login','POST',challenge?{...data,challenge_id:challenge.challenge_id}:{login:data.email,password:data.password});if(out.challenge_id){loginView(out);return;}await boot();}catch(err){root.querySelector('#login-error').innerHTML=`<div class="alert error">${esc(err.message)}</div>`;}finally{b.disabled=false;}};
}
const groups=[['Обзор',['dashboard']],['Команда',['employees','documents','document_types','users','roles','personal_cards']],['Операции',['facilities','posts','instructions','qr_points','shifts','shift_templates','assignments','attendance','no_shows']],['Договоры и контроль',['customers','contracts','licenses','compliance_tasks','service_types','compliance_rules','holidays','contract_templates']],['Заказчики',['reports','incidents','patrols']],['Биржа труда',['vacancies','applications']],['Система',['notifications','audit','settings']]];
const pageNames={dashboard:'Рабочий обзор',tenants:'Организации',health:'Состояние платформы',settings:'Настройки организации',personal_cards:'Личные карточки',no_shows:'Неявки',...Object.fromEntries(groups.flatMap(x=>x[1].map(k=>[k,k])))};
function shell(){const client=APP==='client',platform=APP==='platform';let nav=platform?`<div class="nav-group">Платформа</div>${navLink('dashboard','Обзор платформы')}${navLink('tenants','Организации')}${navLink('health','Состояние системы')}`:'';const wanted=client?['dashboard','facilities','shifts','patrols','incidents','reports','notifications','audit']:null;groups.forEach(([label,keys])=>{const allowed=keys.filter(k=>(!wanted||wanted.includes(k))&&(k==='dashboard'||k==='settings'&&can('settings.update')||k==='audit'&&can('audit.read')||S.schema.resources[k]));if(allowed.length)nav+=`<div class="nav-group">${esc(label)}</div>${allowed.map(k=>navLink(k,name(k))).join('')}`;});root.innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">Ч</span>ЧОППРО</div><div class="eyebrow">${client?'Кабинет заказчика':platform?'Платформа':'Управление охраной'}</div><nav>${nav}</nav><div class="sidebar-bottom"><span class="live-dot"></span>Рабочее демо · Этап 2<br>Данные обновляются из общей БД</div></aside><div class="main"><header class="topbar"><div class="toolbar"><button class="icon-button menu-toggle" aria-label="Открыть меню">${icon('menu')}</button>${platform?`<select class="tenant-switch" id="tenant-switch"><option value="">Вся платформа</option>${S.tenants.map(t=>`<option value="${t.id}" ${S.tenant===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`:`<div><strong>${esc(S.me.tenant?.name||'ЧОППРО')}</strong><div class="breadcrumb">${client?'Пространство заказчика':'Рабочее пространство организации'}</div></div>`}</div><div class="topbar-right"><button class="icon-button" data-nav="notifications" aria-label="Уведомления">${icon('bell')}</button><div class="avatar">${initials(S.me.user.name)}</div><div class="user-meta"><strong>${esc(S.me.user.name)}</strong>${esc(roles[S.me.user.role]||S.me.user.role)}</div><button class="icon-button" id="logout" aria-label="Выйти">${icon('logout')}</button></div></header><main class="container" id="content"></main></div>`;root.querySelector('.menu-toggle').onclick=()=>root.querySelector('.sidebar').classList.toggle('open');root.querySelector('#logout').onclick=async()=>{await api('auth/logout','POST');loginView();};root.querySelector('#tenant-switch')?.addEventListener('change',async e=>{S.tenant=e.target.value;S.refs={};await navigate('dashboard');});root.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));}
function name(k){return S.schema?.names[k]||({dashboard:'Рабочий обзор',tenants:'Организации',health:'Состояние платформы',settings:'Настройки организации',personal_cards:'Личные карточки',no_shows:'Неявки'}[k])||k;}
function navLink(key,label){return `<button class="nav-link ${S.page===key?'active':''}" data-nav="${key}">${icon(key)}<span>${esc(label)}</span></button>`;}
function initials(v){return esc(String(v||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join(''));}
function heading(title,subtitle='',actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="toolbar">${actions}</div></div>`;}
async function boot(){S.me=await api('me');const role=S.me.user.role;if(APP==='client'&&role!=='customer'||APP==='platform'&&role!=='platform_admin'||APP==='admin'&&['customer','guard','platform_admin'].includes(role)){await api('auth/logout','POST');loginView();toast('Для этого пространства нужен аккаунт соответствующей роли',true);return;}S.csrf=S.me.csrf;S.schema=await api('schema');if(APP==='platform')S.tenants=(await api('tenants')).items;await navigate(location.hash.slice(1)||'dashboard');}
async function navigate(page,reset=true){if(!page)page='dashboard';S.page=page;if(reset){S.number=1;S.q='';S.status='';S.filters={};}location.hash=page;shell();const content=root.querySelector('#content');content.innerHTML='<div class="spinner"></div>';try{if(page==='dashboard')await dashboard(content);else if(page==='health')await health(content);else if(page==='settings')await settings(content);else if(page==='facilities')await facilities(content);else if(page==='tenants')await tenants(content);else if(page==='audit')await audit(content);else await listing(content,page);}catch(e){content.innerHTML=heading(name(page))+`<div class="alert error">${esc(e.message)}</div><button class="btn" id="retry">Повторить</button>`;content.querySelector('#retry').onclick=()=>navigate(page,false);}}
function spark(series){const data=series.length?series:Array.from({length:14},(_,i)=>({count:0,date:i}));const max=Math.max(...data.map(x=>Number(x.count)),1);const points=data.map((x,i)=>`${30+i*(640/(Math.max(2,data.length)-1))},${140-(Number(x.count)/max)*115}`).join(' ');return `<svg class="chart" viewBox="0 0 700 160" role="img" aria-label="Заступления за последние 14 дней"><defs><linearGradient id="chart-grad" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#31b6a5" stop-opacity=".2"/><stop offset="100%" stop-color="#31b6a5" stop-opacity="0"/></linearGradient></defs>${[30,65,100,140].map(y=>`<path d="M30 ${y}H680" stroke="#edf1f6"/>`).join('')}<polygon points="30,145 ${points} 670,145" fill="url(#chart-grad)"/><polyline points="${points}" fill="none" stroke="#24a997" stroke-width="2.5"/></svg><div class="chart-labels">${data.filter((_,i)=>i%3===0).map(x=>`<span>${esc(String(x.date).slice(5)||'—')}</span>`).join('')}</div>`;}
function metric(title,value,key,foot='Записей в вашей области доступа'){return `<div class="card metric"><div class="metric-top">${esc(title)}<span class="metric-icon">${icon(key)}</span></div><div class="metric-value">${num(value)}</div><div class="metric-foot">${esc(foot)}</div></div>`;}
async function dashboard(c){if(APP==='platform'&&!S.tenant){const out=await api('health/platform');c.innerHTML=heading('Платформа под контролем','Организации, операционная нагрузка и состояние обработчиков')+`<div class="metrics">${metric('Организации',out.tenants,'facilities')}${metric('В очереди',out.queue.pending,'shifts')}${metric('Ошибки обработки',out.queue.failed,'attendance')}${metric('Файлы в карантине',out.quarantine,'documents')}</div><div class="card">${miniTable(S.tenants,['name','slug','inn','status'],'tenants')}</div>`;bindRecords(c,'tenants');return;}
await loadRefs('shifts');const d=await api('dashboard');const keys=APP==='client'?['facilities','shifts','patrols','reports']:['employees','facilities','shifts','documents'];c.innerHTML=heading(APP==='client'?'Ваши объекты сегодня':'Рабочий обзор','Актуальная картина работы · '+date(d.time),`<button class="btn" id="refresh">${icon('attendance')} Обновить</button>`)+`<div class="metrics">${keys.filter(k=>d.metrics[k]!==undefined).map(k=>metric(name(k),d.metrics[k],k)).join('')}</div><div class="columns"><div class="card"><div class="card-head"><h2>${APP==='client'?'Опубликованные смены':'Заступления на смены'}</h2><span class="status">Последние 14 дней</span></div>${APP==='client'?miniTable(d.upcoming,['name','starts_at','status'],'shifts'):spark(d.series)}</div><div class="card"><div class="card-head"><h2>Требует внимания</h2><button class="link" data-page="notifications">Все уведомления →</button></div>${d.notices.length?d.notices.map(x=>`<div class="notice"><span class="notice-indicator"></span><div><strong>${esc(x.name)}</strong><p>${date(x.created_at)}</p></div></div>`).join(''):'<div class="empty">Новых уведомлений нет</div>'}</div></div><div class="card table-card"><div class="table-toolbar"><h2 style="margin:0;flex:1">Ближайшие смены</h2><button class="link" data-page="shifts">Весь график →</button></div>${miniTable(d.upcoming,['name','post_id','starts_at','ends_at','status'],'shifts')}</div><div class="columns" style="margin-top:22px"><div class="card"><div class="card-head"><h2>Объекты охраны</h2><button class="link" data-page="facilities">Все объекты →</button></div>${d.facilities.map(x=>`<div class="notice"><span class="initials">${icon('facilities')}</span><div><strong>${esc(x.name)}</strong><p>${esc(x.address)}</p></div></div>`).join('')}</div><div class="card"><h2>${APP==='client'?'Опубликованные данные':'Смены без полного состава'}</h2>${APP==='client'?'<p>В кабинете доступны сведения по вашим объектам. Отчёты и происшествия появляются после публикации ответственным сотрудником.</p>':d.unfilled.map(x=>`<div class="notice"><span class="notice-indicator"></span><div><strong>${esc(x.name)}</strong><p>${date(x.starts_at)} · ${statuses[x.status]}</p></div></div>`).join('')||'<div class="empty">Все смены укомплектованы</div>'}</div></div>`;c.querySelector('#refresh').onclick=()=>navigate('dashboard');c.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));bindRecords(c,'shifts');}
const columns={employees:['name','qualification','facility_id','phone','status'],documents:['name','employee_id','type_id','expires_at','status'],facilities:['name','city','customer_id','status'],posts:['name','facility_id','qualification','headcount','status'],shifts:['name','post_id','starts_at','ends_at','status'],assignments:['name','employee_id','shift_id','status'],attendance:['name','employee_id','event_type','server_time','status'],contracts:['name','number','customer_id','ends_at','status'],compliance_tasks:['name','deadline','rule_version','status'],vacancies:['name','city','salary_from','salary_to','pinned_rank','status'],users:['name','email','role','status'],reports:['name','period','published','status'],audit:['created_at','action','entity_type','ip']};
function cell(key,value){if(key==='status'||key==='scan_status')return badge(value);if(key==='role')return esc(roles[value]||value);if(['created_at','updated_at','starts_at','ends_at','server_time','client_time','deadline','sent_at','finished_at'].includes(key))return esc(date(value));if(key==='published')return value==1?badge('PUBLISHED'):badge('DRAFT');if(key==='pinned_rank')return value?`<span class="status green">Закреп №${num(value)}</span>`:'—';if(key.endsWith('_id')){const resource=S.schema?.references[key];return esc(S.refs[resource]?.find(x=>x.id===value)?.name||String(value||'—').slice(0,12));}if(Array.isArray(value)||value&&typeof value==='object')return esc(JSON.stringify(value));if(key.includes('salary')||key==='amount')return num(value)+' ₽';return esc(String(value??'—').slice(0,130));}
function miniTable(items,keys,kind){return `<div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(S.schema?.labels[k]||({created_at:'Дата',action:'Действие',entity_type:'Тип записи',ip:'IP',pinned_rank:'Продвижение',event_type:'Событие',server_time:'Время сервера'}[k])||k)}</th>`).join('')}<th></th></tr></thead><tbody>${items.map(row=>`<tr data-record="${row.id}" data-kind="${kind}">${keys.map((k,i)=>`<td>${i===0&&k==='name'?`<div class="record-name"><span class="initials">${initials(row.name)}</span><div><strong>${esc(row.name)}</strong><span class="small">${esc(row.number||row.badge||row.city||'')}</span></div></div>`:cell(k,row[k])}</td>`).join('')}<td class="muted">${icon('arrow')}</td></tr>`).join('')||`<tr><td colspan="${keys.length+1}" class="empty">Записей пока нет</td></tr>`}</tbody></table></div>`;}
async function loadRefs(kind){const fields={...(S.schema?.resources[kind]||{}),...(['users','shifts'].includes(kind)?{facility_id:'char(36)'}:{})};const names=[...new Set(Object.keys(fields).map(f=>S.schema.references[f]).filter(k=>k&&S.schema.resources[k]&&!S.refs[k]))];await Promise.all(names.map(async k=>{try{S.refs[k]=(await api(k,'GET',null,{limit:500,sort:'name',direction:'asc'})).items;}catch{S.refs[k]=[];}}));}
async function listing(c,kind){if(!S.schema.resources[kind])throw Error('Раздел недоступен для вашей роли');await loadRefs(kind);const out=await api(kind,'GET',null,{page:S.number,limit:40,q:S.q,status:S.status,...S.filters});S.data=out;const fields=S.schema.resources[kind];const extraFilters=['facility_id','post_id','employee_id'].filter(k=>fields[k]&&S.refs[S.schema.references[k]]);let keys=columns[kind]||['name',...Object.keys(fields).filter(k=>k!=='name'&&!['text','source','internal_note','file_path','sha256','mime','description','payload','permissions','token'].includes(k)).slice(0,4)];const subtitle=kind==='compliance_tasks'?'Подготовка/контроль, не отправка. Подтверждение подачи вносит ответственное лицо.':`${num(out.total)} записей · изменения сохраняются в БД`;const create=can(kind+'.create')&&!['attendance','notifications','no_shows','instructions','document_reviews','outbox','report_receipts','contract_versions'].includes(kind);c.innerHTML=heading(name(kind),subtitle,`${can(kind+'.export')?'<button class="btn" id="export">'+icon('download')+' Экспорт CSV</button>':''}${['employees','customers','facilities'].includes(kind)&&can(kind+'.create')?'<button class="btn" id="import">Импорт CSV</button>':''}${create?'<button class="btn primary" id="create">'+icon('plus')+' Добавить</button>':''}`)+`<div class="card table-card"><form class="table-toolbar" id="filters"><input name="q" placeholder="Поиск по названию, номеру, телефону…" aria-label="Поиск" value="${esc(S.q)}">${fields.status?`<select name="status" aria-label="Статус"><option value="">Все статусы</option>${(S.schema.statuses[kind]||[]).map(s=>`<option value="${s}" ${s===S.status?'selected':''}>${esc(statuses[s]||s)}</option>`).join('')}</select>`:''}${extraFilters.map(key=>`<select name="${key}" aria-label="${esc(S.schema.labels[key])}"><option value="">Все: ${esc(S.schema.labels[key])}</option>${S.refs[S.schema.references[key]].map(r=>`<option value="${r.id}" ${r.id===S.filters[key]?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`).join('')}${['employees','documents'].includes(kind)?`<input name="expires_before" type="date" aria-label="Срок документов до" title="Документы истекают до даты" value="${esc(S.filters.expires_before||'')}">`:''}<button class="btn">${icon('search')} Найти</button>${kind==='shifts'?'<button type="button" class="btn" id="calendar">Неделя</button>':''}</form>${miniTable(out.items,keys,kind)}<div class="pagination"><span>Страница ${S.number} из ${Math.max(1,out.pages||1)} · всего ${num(out.total)}</span><div class="toolbar"><button class="btn small" id="prev" ${S.number<=1?'disabled':''}>← Назад</button><button class="btn small" id="next" ${S.number>=(out.pages||1)?'disabled':''}>Далее →</button></div></div></div>`;c.querySelector('#filters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);S.q=f.get('q');S.status=f.get('status')||'';S.filters=Object.fromEntries([...f.entries()].filter(([key])=>!['q','status'].includes(key)));S.number=1;navigate(kind,false);};c.querySelector('#prev').onclick=()=>{S.number--;navigate(kind,false);};c.querySelector('#next').onclick=()=>{S.number++;navigate(kind,false);};c.querySelector('#create')?.addEventListener('click',()=>edit(kind));c.querySelector('#import')?.addEventListener('click',()=>importForm(kind));c.querySelector('#export')?.addEventListener('click',()=>window.open(url(kind+'/export'),'_blank','noopener'));c.querySelector('#calendar')?.addEventListener('click',()=>calendar());bindRecords(c,kind);}
function bindRecords(c,fallback){c.querySelectorAll('[data-record]').forEach(el=>el.onclick=()=>detail(el.dataset.kind||fallback,el.dataset.record));}
async function detail(kind,id){try{let row;if(kind==='tenants')row=S.tenants.find(x=>x.id===id);else row=(await api(kind+'/'+id)).item;await loadRefs(kind);const fields=S.schema.resources[kind]||Object.fromEntries(Object.keys(row).map(k=>[k,'text']));const actions=[];if(kind==='tenants'){actions.push(['edit','Настроить организацию']);}else{if(can(kind+'.update')&&!['attendance','assignments','notifications','no_shows','instructions','document_reviews','contract_versions','outbox'].includes(kind))actions.push(['edit','Редактировать']);if(can(kind+'.delete')&&!['attendance','notifications','no_shows','document_reviews','contract_versions','outbox'].includes(kind))actions.push(['delete','Удалить']);if(kind==='documents'){if(can('documents.review'))actions.push(['review','Проверить документ']);if(can('documents.download'))actions.push(['download','Скачать файл']);actions.push(['history','История проверок']);if(can('documents.create'))actions.push(['upload','Загрузить новый файл']);}if(['licenses','contracts','compliance_tasks'].includes(kind))actions.push(['files','Файлы и подтверждения']);if(kind==='contracts'){actions.push(['checks','Проверить реквизиты'],['history','История договора'],['signage','Уведомительная табличка']);if(can('contracts.update')&&row.status==='DRAFT')actions.push(['activate','Активировать']);}if(kind==='shifts'&&can('shifts.update')){if(!Number(row.published))actions.push(['publish','Опубликовать']);if(row.status!=='CANCELLED')actions.push(['cancel','Отменить смену']);}if(kind==='assignments'&&can('assignments.update'))actions.push(['replace','Заменить сотрудника'],['history','История замен']);if(kind==='attendance'&&row.status==='REQUIRES_REVIEW'&&can('attendance.override'))actions.push(['override','Принять решение']);if(kind==='vacancies'&&can('vacancies.pin'))actions.push(['pin','Ручной закреп']);if(kind==='compliance_tasks')actions.push(['draft','Подготовить черновик']);if(kind==='shift_templates'&&can('shifts.create'))actions.push(['generate','Создать смены по шаблону']);if(kind==='qr_points'&&can('qr_points.update'))actions.push(['rotate','Отозвать и заменить QR']);if(kind==='reports'&&can('reports.acknowledge'))actions.push(['acknowledge','Ознакомлен с отчётом'],['pdf','Скачать PDF']);if(['service_types','compliance_rules','contract_templates'].includes(kind)&&can(kind+'.create'))actions.push(['newversion','Создать новую версию']);if(kind==='users'&&can('users.update'))actions.push(['invite','Новое приглашение']);}
showDialog(row.name||name(kind),`<div class="detail-actions">${actions.map(([action,label])=>`<button class="btn small ${['delete','cancel'].includes(action)?'danger':''}" data-action="${action}">${esc(label)}</button>`).join('')}</div>${kind==='qr_points'&&row.token?'<div id="qr-svg"></div>':''}${kind==='facilities'?geo(row):''}<dl class="detail-grid">${Object.keys(fields).filter(k=>!['file_path','sha256','internal_note'].includes(k)||kind!=='reports'&&S.me.user.role!=='customer').filter(k=>row[k]!==undefined&&!['file_path'].includes(k)).map(k=>`<div class="detail-field"><dt>${esc(S.schema.labels[k]||k)}</dt><dd>${cell(k,row[k])}</dd></div>`).join('')}<div class="detail-field"><dt>Создано</dt><dd>${date(row.created_at)}</dd></div><div class="detail-field"><dt>Версия</dt><dd>${num(row.version)}</dd></div></dl>`);if(kind==='qr_points'&&row.token)dialog.querySelector('#qr-svg').innerHTML=window.chopproQr(row.token);dialog.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>recordAction(kind,row,b.dataset.action));}catch(e){toast(e.message,true);}}
const systemFields=['file_path','sha256','mime','scan_status','pinned_rank','pinned_at','token','instruction_version','author_id','actor_id','published_by','source_id','server_time','idempotency_key','duration_minutes','legal_hold_until'];
async function edit(kind,row=null){await loadRefs(kind);const fields=S.schema.resources[kind];const values={...S.schema.defaults?.[kind],...(row||{})};S.editing=values;let wanted=Object.keys(fields).filter(k=>!systemFields.includes(k));if(kind==='documents')wanted=wanted.filter(k=>!['status'].includes(k));if(kind==='shifts')wanted=wanted.filter(k=>!['status','published'].includes(k));if(kind==='contracts')wanted=wanted.filter(k=>!['status','override_reason'].includes(k));if(['service_types','compliance_rules','contract_templates'].includes(kind)&&row){toast('Исторические версии изменять нельзя. Создайте новую версию.',true);return;}
showDialog((row?'Редактировать: ':'Добавить: ')+name(kind),`<form id="edit-form"><div class="form-grid">${wanted.map(k=>field(k,fields[k],values[k],kind)).join('')}</div>${kind==='documents'&&!row?'<div class="upload-area"><label>Файл документа · PDF, PNG или JPEG, до 10 МБ<input type="file" name="file" accept="application/pdf,image/png,image/jpeg" required></label><p class="small" style="margin-top:10px">Файл будет помещён в карантин до антивирусной проверки.</p></div>':''}<div id="form-error"></div><div class="form-footer"><button type="button" class="btn" data-cancel>Отмена</button><button class="btn primary">${row?'Сохранить изменения':'Создать'}</button></div></form>`);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('.primary');b.disabled=true;try{const data=readForm(e.target,fields);if(row)data.version=row.version;let out;if(kind==='documents'&&!row){const f=new FormData();Object.entries(data).forEach(([k,v])=>f.append(k,typeof v==='object'?JSON.stringify(v):v??''));f.append('file',e.target.elements.file.files[0]);out=await api('documents/upload','POST',f);}else out=await api(kind+(row?'/'+row.id:''),row?'PUT':'POST',data);dialog.close();S.refs[kind]=null;toast(out.invitation_token?'Приглашение создано':'Изменения сохранены');if(out.warnings?.length)showDialog('Предупреждения о нагрузке','<div class="alert">'+out.warnings.map(esc).join('<br>')+'</div>');if(out.invitation_token)invitation(out.invitation_token);await navigate(kind,false);}catch(err){dialog.querySelector('#form-error').innerHTML=`<div class="alert error" style="margin-top:15px">${esc(err.message)}${err.details?.field?': '+esc(S.schema.labels[err.details.field]||err.details.field):''}</div>`;}finally{b.disabled=false;}};}
function field(key,type,value,kind){const label=S.schema?.labels[key]||({owner_email:'Email владельца',owner_name:'Имя владельца',inn:'ИНН',domain:'Домен',slug:'Адрес организации',severity:'Важность',category:'Категория',content:'Содержание',polygon:'Полигон: список [широта, долгота]',receipt:'Квитанция / входящий номер'}[key])||key;const required=(S.schema?.required?.[kind]||['name']).includes(key);const attrs=`name="${key}" ${required?'required':''}`;let input;const ref=S.schema?.references[key];if(ref&&S.refs[ref])input=`<select ${attrs}><option value="">Выберите…</option>${S.refs[ref].map(r=>`<option value="${r.id}" ${r.id===value?'selected':''}>${esc(r.name)}${r.status?' · '+esc(statuses[r.status]||r.status):''}</option>`).join('')}</select>`;else if(key==='status')input=`<select ${attrs}>${(S.schema.statuses[kind]||['ACTIVE','INACTIVE']).map(s=>`<option value="${s}" ${s===value?'selected':''}>${esc(statuses[s]||s)}</option>`).join('')}</select>`;else if(key==='role')input=`<select ${attrs}>${S.schema.roles.filter(k=>k!=='platform_admin').map(k=>`<option value="${k}" ${k===value?'selected':''}>${esc(roles[k]||k)}</option>`).join('')}</select>`;else if(key==='scopes')input=`<select name="scopes" multiple size="5">${(S.refs.facilities||[]).map(r=>`<option value="${r.id}" ${(value||[]).includes(r.id)?'selected':''}>${esc(r.name)}</option>`).join('')}</select><small>Пустой список — все разрешённые объекты</small>`;else if(type==='tinyint')input=`<select ${attrs}><option value="0" ${!Number(value)?'selected':''}>Нет</option><option value="1" ${Number(value)?'selected':''}>Да</option></select>`;else if(type==='text'||type==='json')input=`<textarea ${attrs} rows="${type==='json'?3:4}" placeholder="${type==='json'?'Список или объект JSON':'Введите текст'}">${esc(typeof value==='object'?JSON.stringify(value,null,2):value||'')}</textarea>`;else{const inputType=type==='date'?'date':type==='datetime'?'datetime-local':type==='int'||type.startsWith('decimal')?'number':key==='email'||key==='owner_email'?'email':'text';let v=value??'';if(type==='datetime'&&v){if(kind==='shifts'){const post=S.refs.posts?.find(p=>p.id===S.editing?.post_id);const facility=S.refs.facilities?.find(f=>f.id===post?.facility_id);const tz=facility?.timezone||S.me?.tenant?.settings?.timezone||'Europe/Moscow';const d=new Date(String(v).replace(' ','T')+(String(v).includes('T')?'':'Z'));v=new Intl.DateTimeFormat('sv-SE',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d).replace(' ','T');}else v=String(v).replace(' ','T').slice(0,16);}input=`<input ${attrs} type="${inputType}" ${inputType==='number'?'step="any"':''} value="${esc(v)}">`;}
return `<label class="${type==='text'||type==='json'||key==='scopes'?'full':''}">${esc(label)}${required?' *':''}${input}</label>`;}
function readForm(form,fields){const fd=new FormData(form),data={};for(const [key,type]of Object.entries(fields)){if(!fd.has(key))continue;let v=fd.get(key);if(key==='scopes')v=fd.getAll(key);else if(type==='json'){if(!v)v=[];else{try{v=JSON.parse(v);}catch{v=String(v).split(',').map(x=>x.trim()).filter(Boolean);}}}else if(type==='tinyint'||type==='int'||type.startsWith('decimal'))v=v===''?null:Number(v);else if(v==='')v=null;data[key]=v;}return data;}
async function actionForm(title,path,fields,values={},method='POST',after=null){showDialog(title,`<form><div class="form-grid">${Object.entries(fields).map(([k,t])=>field(k,t,values[k],path.split('/')[0]==='tenants'?'tenants':'actions')).join('')}</div><div id="action-error"></div><div class="form-footer"><button class="btn primary">Подтвердить</button></div></form>`);dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=readForm(e.target,fields);const out=await api(path,method,data);dialog.close();toast('Действие выполнено');if(APP==='jobs'){await jobs();if(after)after(out);}else{await navigate(S.page,false);if(after)after(out);}}catch(err){dialog.querySelector('#action-error').innerHTML=`<div class="alert error" style="margin-top:15px">${esc(err.message)}</div>`;}finally{b.disabled=false;}};}
async function recordAction(kind,row,action){try{const path=kind+'/'+row.id+'/'+action;if(action==='signage')return signageForm(row);if(action==='files')return attachmentForm(kind,row);if(action==='edit'){if(kind==='tenants')return tenantForm(row);return edit(kind,row);}if(action==='delete'){return actionForm('Удалить запись?',kind+'/'+row.id,{}, {},'DELETE');}if(action==='download'||action==='pdf'){window.open(url(path),'_blank','noopener');return;}if(action==='history'||action==='checks'||action==='draft'){const out=await api(path);showDialog(action==='checks'?'Проверка договора':action==='draft'?'Черновик для ручной подачи':'История записи',action==='checks'?`<div class="alert ${out.issues.length?'error':'success'}">${out.issues.length?out.issues.map(esc).join('<br>'):'Обязательные реквизиты заполнены'}</div><p>${esc(out.notice)}</p>`:action==='draft'?`<pre>${esc(out.text)}</pre><button class="btn" id="save-draft">Скачать TXT</button>`:`${(out.items||[]).map(x=>`<div class="card" style="margin-bottom:10px"><strong>${esc(x.name)}</strong><p>${date(x.created_at)}</p><pre>${esc(JSON.stringify(x,null,2))}</pre></div>`).join('')||'<div class="empty">История пока пуста</div>'}`);dialog.querySelector('#save-draft')?.addEventListener('click',()=>downloadText(out.text,'compliance-draft.txt'));return;}if(action==='review')return actionForm('Результат ручной проверки',path,{decision:'varchar(32)',reason:'text'},{decision:'VALID',reason:''});if(action==='pin')return pinForm(row);if(action==='replace'){await loadRefs('assignments');return actionForm('Замена сотрудника',path,{employee_id:'char(36)',reason:'text',version:'int'},{version:row.version});}if(action==='cancel'||action==='override'||action==='activate')return actionForm(action==='cancel'?'Отмена смены':action==='override'?'Ручное подтверждение события':'Активация договора',path,{reason:'text'});if(action==='generate')return actionForm('Создание смен по шаблону',path,{from:'date',to:'date'},{from:new Date().toISOString().slice(0,10),to:new Date(Date.now()+7*864e5).toISOString().slice(0,10)});if(action==='upload')return edit('documents');if(action==='newversion'){const fields=Object.fromEntries(Object.entries(S.schema.resources[kind]).filter(([k])=>!systemFields.includes(k)&&!['rule_version','revision','published'].includes(k)));return actionForm('Новая версия: '+row.name,kind+'/'+row.id+'/new-version',fields,row);}if(action==='invite'){const out=await api('users/'+row.id+'/invite','POST',{});return invitation(out.invitation_token);}await api(path,'POST');dialog.close();toast('Действие выполнено');await navigate(S.page,false);}catch(e){toast(e.message,true);}}
function pinForm(row){showDialog('Ручной закреп вакансии',`<p>Три места в верхней части биржи труда. Закреп действует до снятия администратором.</p><form><label>Место<select name="rank"><option value="">Без закрепа</option>${[1,2,3].map(i=>`<option value="${i}" ${Number(row.pinned_rank)===i?'selected':''}>Закреп №${i}</option>`).join('')}</select></label><div id="pin-error"></div><div class="form-footer"><button class="btn primary">Сохранить закреп</button></div></form>`);dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const rank=new FormData(e.target).get('rank');await api('vacancies/'+row.id+'/pin','POST',{rank:rank?Number(rank):null});dialog.close();toast('Закреп обновлён');await navigate('vacancies',false);}catch(err){dialog.querySelector('#pin-error').innerHTML=`<div class="alert error">${esc(err.message)}</div>`;}};}
function downloadText(content,name){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function invitation(token){showDialog('Приглашение пользователя',`<p>Передайте пользователю этот токен. Он действует 7 дней. На странице входа выберите «Принять приглашение».</p><pre>${esc(token)}</pre>`);}
async function importForm(kind){let preview=null,batch=null;showDialog('Импорт: '+name(kind),`<p>CSV, разделитель — запятая. Шаблон версии 1. Обязательные поля: ${esc((S.schema.required[kind]||[]).join(', '))}.</p><form><input type="file" name="csv" accept=".csv,text/csv" required><div class="form-footer"><button class="btn primary">Проверить строки</button></div></form><div id="import-result"></div>`);dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const csv=await e.target.elements.csv.files[0].text();preview=await api('imports/'+kind+'/preview','POST',{csv,template_version:1});const box=dialog.querySelector('#import-result');box.innerHTML=`<div class="alert ${preview.errors?'':'success'}">Корректных строк: ${preview.valid}. Ошибок: ${preview.errors}.</div><pre>${esc(preview.rows.map(r=>'Строка '+r.line+': '+(r.valid?'OK · '+r.data.name:r.error)).join('\n'))}</pre><button class="btn primary" id="apply-import" ${!preview.valid?'disabled':''}>Импортировать корректные строки</button>`;box.querySelector('button').onclick=async()=>{const out=await api('imports/'+kind+'/apply','POST',{csv,template_version:1});batch=out.batch_id;box.innerHTML=`<div class="alert success">Добавлено ${out.inserted} записей.</div><button class="btn" id="rollback">Откатить импорт</button>`;box.querySelector('button').onclick=async()=>{const undo=await api('imports/'+batch+'/rollback','POST',{});dialog.close();toast('Откат выполнен: '+undo.rolled_back);await navigate(kind,false);};await navigate(kind,false);};}catch(err){toast(err.message,true);}};}
function geo(f){return `<svg class="geo" viewBox="0 0 500 200" role="img" aria-label="Геозона объекта"><defs><pattern id="map-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#e0e8f0"/></pattern></defs><rect width="500" height="200" fill="url(#map-grid)"/><path d="M0 150L500 50 M150 0L270 200" stroke="white" stroke-width="20"/><path d="M0 150L500 50 M150 0L270 200" stroke="#d9e3ee" stroke-width="1"/><circle cx="250" cy="94" r="65" fill="#1cb29a20" stroke="#25ab96" stroke-dasharray="4 3"/><circle cx="250" cy="94" r="8" fill="#159b89" stroke="white" stroke-width="3"/><rect x="170" y="165" width="160" height="25" rx="5" fill="white"/><text x="250" y="182" text-anchor="middle" font-size="11" fill="#60758a">Геозона · ${num(f.radius)} м</text><text x="15" y="23" font-size="10" fill="#7f93a6">${esc(f.lat)}, ${esc(f.lng)}</text></svg>`;}
async function facilities(c){await loadRefs('facilities');const out=await api('facilities','GET',null,{limit:60,q:S.q});S.data=out;c.innerHTML=heading('Объекты охраны',`${num(out.total)} объектов в вашей области доступа`,can('facilities.create')?'<button class="btn primary" id="create">'+icon('plus')+' Новый объект</button>':'')+`<form class="table-toolbar" id="facility-search"><input name="q" placeholder="Поиск по названию или адресу" value="${esc(S.q)}"><button class="btn">Найти</button></form><div class="content-grid">${out.items.map(f=>`<article class="card facility-card" data-record="${f.id}" data-kind="facilities"><div class="card-head"><span class="metric-icon">${icon('facilities')}</span>${badge(f.status)}</div><h2>${esc(f.name)}</h2><div class="location">${esc(f.address)}</div>${geo(f)}<div class="toolbar"><span class="small muted">${esc(f.timezone)}</span><button class="link" style="margin-left:auto">Открыть карточку →</button></div></article>`).join('')}</div>`;c.querySelector('#create')?.addEventListener('click',()=>edit('facilities'));c.querySelector('form').onsubmit=e=>{e.preventDefault();S.q=new FormData(e.target).get('q');navigate('facilities',false);};bindRecords(c,'facilities');}
async function calendar(){const from=new Date();from.setUTCHours(0,0,0,0);const to=new Date(from.getTime()+7*864e5);const out=await api('shifts','GET',null,{from:from.toISOString(),to:to.toISOString(),limit:500,sort:'starts_at',direction:'asc'});showDialog('График на неделю',`<div class="calendar-days">${Array.from({length:7},(_,i)=>{const day=new Date(from.getTime()+i*864e5);const key=day.toISOString().slice(0,10);return `<div class="day"><h3>${day.toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'short'})}</h3>${out.items.filter(x=>x.starts_at.startsWith(key)).map(x=>`<div class="day-shift ${!Number(x.published)?'draft':''}" data-record="${x.id}" data-kind="shifts"><b>${esc(x.name)}</b>${date(x.starts_at)}<br>${badge(x.status)}</div>`).join('')||'<span class="muted small">Нет смен</span>'}</div>`;}).join('')}</div>`);bindRecords(dialog,'shifts');}
async function settings(c){const out=await api('settings');const labels={timezone:'Часовой пояс',language:'Язык',reminder_days:'Дни напоминаний',default_radius:'Радиус геозоны по умолчанию, м',late_minutes:'Порог опоздания, мин',checkin_early_minutes:'Раннее заступление, мин',checkin_late_minutes:'Позднее заступление, мин',gps_max_accuracy:'Максимальная погрешность GPS, м',weekly_hours_warning:'Порог часов в неделю',expiring_days:'Документ истекает за, дней'};const fields=Object.fromEntries(Object.keys(labels).map(k=>[k,k==='reminder_days'?'json':['timezone','language'].includes(k)?'varchar(64)':'int']));S.schema.labels={...S.schema.labels,...labels};c.innerHTML=heading('Настройки организации','Изменения применяются к новым событиям и записываются в аудит')+`<div class="card"><form><div class="form-grid">${Object.entries(fields).map(([k,t])=>field(k,t,out.settings[k],'settings')).join('')}</div><div class="form-footer"><button class="btn primary">Сохранить настройки</button></div></form></div>`;c.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('settings','PUT',{...readForm(e.target,fields),version:out.version});toast('Настройки сохранены');await navigate('settings');}catch(err){toast(err.message,true);}};}
async function tenants(c){S.tenants=(await api('tenants')).items;c.innerHTML=heading('Организации',`${S.tenants.length} организаций на платформе`,'<button class="btn primary" id="new-tenant">'+icon('plus')+' Добавить организацию</button>')+`<div class="card table-card">${miniTable(S.tenants,['name','slug','inn','domain','status'],'tenants')}</div>`;c.querySelector('#new-tenant').onclick=()=>tenantForm();bindRecords(c,'tenants');}
function tenantForm(row=null){
 const fields={name:'varchar(200)',slug:'varchar(64)',inn:'varchar(12)',domain:'varchar(200)',status:'varchar(32)',settings:'json',features:'json'};
 if(!row){fields.owner_name='varchar(200)';fields.owner_email='varchar(200)';}
 S.schema.statuses.tenants=['ACTIVE','SUSPENDED'];
 const values={...(row||{}),settings:typeof row?.settings==='string'?JSON.parse(row.settings):(row?.settings||{timezone:'Europe/Moscow',language:'ru',reminder_days:[30,14,7,1],default_radius:150,late_minutes:15}),features:typeof row?.features==='string'?JSON.parse(row.features):(row?.features||{core:true,compliance:true,jobs:true})};
 if(row)fields.version='int';
 actionForm(row?'Настройки организации':'Новая организация','tenants'+(row?'/'+row.id:''),fields,values,row?'PUT':'POST',out=>{if(out.invitation_token)invitation(out.invitation_token);});
}
async function health(c){const out=await api('health/platform');c.innerHTML=heading('Состояние платформы','Контроль базы, очередей, карантина и фоновой обработки')+`<div class="metrics">${metric('Организации',out.tenants,'facilities')}${metric('Ожидают обработки',out.queue.pending,'shifts')}${metric('Ошибки очереди',out.queue.failed,'attendance')}${metric('Файлы в карантине',out.quarantine,'documents')}</div><div class="card"><h2>Фоновая обработка</h2><p>Последний запуск: ${out.worker?date(out.worker.last_run):'Ещё не запускалась'}</p><button class="btn primary" id="worker">Запустить обработчик</button>${S.tenant?'<button class="btn" id="support" style="margin-left:10px">Временный доступ поддержки</button>':''}<div id="worker-result"></div></div>`;c.querySelector('#worker').onclick=async()=>{try{const result=await api('worker','POST');c.querySelector('#worker-result').innerHTML=`<div class="alert success" style="margin-top:15px">Обработка завершена. Документы: ${num(result.documents)}. Напоминания: ${num(result.reminders)}. Неявки: ${num(result.no_shows)}.</div>`;}catch(e){toast(e.message,true);}};c.querySelector('#support')?.addEventListener('click',()=>actionForm('Временный доступ поддержки','support/access',{reason:'text',minutes:'int'},{minutes:15}));}
async function audit(c){const out=await api('audit','GET',null,{q:S.q});c.innerHTML=heading('Журнал аудита','Действия пользователей и события безопасности',can('audit.export')?'<button class="btn" id="audit-export">'+icon('download')+' Экспорт CSV</button>':'')+`<div class="card table-card"><form id="audit-filter" class="table-toolbar"><input name="action" placeholder="Действие, например user.updated"><input name="entity_id" placeholder="UUID записи"><input name="from" type="date" aria-label="Начало периода"><input name="to" type="date" aria-label="Конец периода"><button class="btn">Найти</button></form><div id="audit-table">${auditTable(out.items)}</div></div>`;c.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const query=Object.fromEntries(new FormData(e.target));const filtered=await api('audit','GET',null,query);c.querySelector('#audit-table').innerHTML=auditTable(filtered.items);}catch(err){toast(err.message,true);}};c.querySelector('#audit-export')?.addEventListener('click',()=>window.open(url('audit/export'),'_blank','noopener'));}
function auditTable(items){return `<div class="table-wrap"><table><thead><tr><th>Время</th><th>Действие</th><th>Запись</th><th>IP</th><th>Подробности</th></tr></thead><tbody>${items.map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.action)}</td><td>${esc(x.entity_type)}</td><td>${esc(x.ip)}</td><td><details><summary>Открыть</summary><pre>${esc(JSON.stringify(x.metadata,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div>`;}
async function jobs(){const out=await api('public/jobs','GET',null,{q:S.q,city:S.status});root.innerHTML=`<header class="jobs-header"><div class="brand"><span class="brand-mark">Ч</span>ЧОППРО <span class="small muted" style="font-weight:400;letter-spacing:0;margin-left:10px">Биржа труда</span></div><a class="btn" href="${BASE}/demo.php?app=admin" target="_blank" rel="noopener">Кабинет работодателя ↗</a></header><section class="jobs-hero"><div class="eyebrow">Работа в охранной отрасли</div><h1>Надёжная работа.<br>Проверенные работодатели.</h1><p>Вакансии охранников, контролёров и старших смен. Подберите объект и график, которые подходят вам.</p><form class="jobs-search"><input name="q" aria-label="Название вакансии" placeholder="Должность, организация или ключевое слово" value="${esc(S.q)}"><select name="city" aria-label="Город"><option value="">Все города</option>${out.cities.map(city=>`<option ${city===S.status?'selected':''}>${esc(city)}</option>`).join('')}</select><button class="btn primary">${icon('search')} Найти работу</button></form></section><main class="jobs-content"><div class="page-head"><div><h2 style="margin:0">${num(out.total)} вакансий</h2><p class="small" style="margin:5px 0 0">Открытые предложения от охранных организаций</p></div><span class="status green">Сначала закреплённые</span></div><div class="jobs-grid">${out.items.map(j=>`<article class="card job-card ${j.pinned_rank?'pinned':''}">${j.pinned_rank?`<div class="pin-label">★ Закреп №${j.pinned_rank}</div>`:''}<div class="job-company">${esc(j.tenant_name)} · ${esc(j.city)}</div><h2>${esc(j.name)}</h2><div class="job-salary">${num(j.salary_from)}–${num(j.salary_to)} ₽</div><div class="job-details"><span>${esc(j.schedule)}</span><span>Разряд ${num(j.qualification)}</span><span>Официальное оформление</span></div><p>${esc(j.description)}</p><button class="btn primary" data-apply="${j.id}">Откликнуться ${icon('arrow')}</button></article>`).join('')||'<div class="empty">По выбранным условиям вакансий нет</div>'}</div><p class="small muted" style="margin-top:25px">Демонстрационные вакансии. Отклики сохраняются в тестовой базе работодателя.</p></main>`;root.querySelector('form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);S.q=data.get('q');S.status=data.get('city');jobs();};root.querySelectorAll('[data-apply]').forEach(b=>b.onclick=()=>actionForm('Отклик на вакансию','public/jobs/'+b.dataset.apply+'/apply',{name:'varchar(200)',phone:'varchar(32)',email:'varchar(200)',message:'text'},{},'POST',()=>showDialog('Отклик сохранён','<div class="alert success">Спасибо! Ваш отклик доступен работодателю в разделе «Отклики».</div>')));}
(async()=>{try{S.csrf=(await api('csrf')).csrf;if(APP==='jobs'){await jobs();return;}try{await boot();}catch(e){if(['AUTH_REQUIRED','SESSION_EXPIRED'].includes(e.code))loginView();else{loginView();toast(e.message,true);}}}catch(e){root.innerHTML=`<div class="loading"><h1>ЧОППРО</h1><div class="alert error">${esc(e.message)}</div><button class="btn" id="page-reload">Повторить</button></div>`;}})();

setTimeout(()=>{const check=()=>fetch((document.body.dataset.base||'')+'/release-status.php?check=1',{credentials:'same-origin'}).catch(()=>{});check();setInterval(check,300000);},2000);

async function attachmentForm(kind,row){
 const out=await api(kind+'/'+row.id+'/files');
 showDialog('Файлы: '+row.name,`<div>${out.items.map(f=>`<div class="notice"><div><strong>${esc(f.name)}</strong><p>${date(f.created_at)} · ${badge(f.scan_status)}</p>${f.scan_status==='CLEAN'?`<a class="btn small" href="${url('files/'+f.id+'/download')}" target="_blank" rel="noopener">Скачать</a>`:''}</div></div>`).join('')||'<p>Вложения пока не добавлены.</p>'}</div>${can(kind+'.update')?'<form class="upload-area"><input type="file" name="file" accept="application/pdf,image/png,image/jpeg" required><p class="small">Файл доступен после антивирусной проверки.</p><button class="btn primary">Загрузить файл</button></form>':''}`);
 dialog.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();try{const file=new FormData(e.target);await api(kind+'/'+row.id+'/files','POST',file);toast('Файл сохранён для проверки');await attachmentForm(kind,row);}catch(err){toast(err.message,true);}});
}

async function signageForm(row){const out=await api('contracts/'+row.id+'/signage');showDialog('Уведомительная табличка',`<pre>${esc(out.layout)}</pre><p>${esc(out.notice)}</p><button class="btn" id="signage-download">Скачать макет TXT</button><form style="margin-top:20px"><label class="check-label"><input type="checkbox" name="placed" ${out.checklist.placed?'checked':''}> Табличка физически размещена</label><label class="check-label"><input type="checkbox" name="required" ${out.checklist.required?'checked':''}> Требуется размещение</label><label>Реквизиты доказательства<input name="proof" value="${esc(out.checklist.proof||'')}"></label><div class="form-footer"><button class="btn primary">Сохранить чек-лист</button></div></form>`);dialog.querySelector('#signage-download').onclick=()=>downloadText(out.layout,'signage.txt');dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('contracts/'+row.id,'PUT',{version:row.version,signage:{required:f.has('required'),placed:f.has('placed'),proof:f.get('proof'),note:out.notice}});dialog.close();toast('Чек-лист сохранён');await navigate('contracts',false);}catch(err){toast(err.message,true);}};}
